mapper.select:
WITH kline AS ( SELECT symbol, COUNT(*) AS record_count, MIN(date)::text AS kline_start, MAX(date)::text AS kline_end FROM tech_daily WHERE symbol IN
#{symbol}
NULL
GROUP BY symbol ), latest_basic AS ( SELECT d.symbol, d.close, d.total_mv, d.pe_ttm FROM fundamental_daily_basic d JOIN (SELECT symbol, MAX(trade_date) AS md FROM fundamental_daily_basic WHERE symbol IN
#{symbol}
NULL
GROUP BY symbol) t ON t.symbol = d.symbol AND t.md = d.trade_date ), latest_report AS ( SELECT r.symbol, r.n_income, r.revenue FROM fundamental_income r JOIN (SELECT symbol, MAX(end_date) AS md FROM fundamental_income WHERE report_type = '1' AND symbol IN
#{symbol}
NULL
GROUP BY symbol) t ON t.symbol = r.symbol AND t.md = r.end_date WHERE r.report_type = '1' ) SELECT k.symbol AS symbol, COALESCE(k.record_count, 0) AS record_count, k.kline_start AS kline_start, k.kline_end AS kline_end, b.close AS latest_close, b.total_mv AS total_mv, b.pe_ttm AS pe_ttm, CASE WHEN r.revenue IS NULL OR r.revenue = 0 THEN NULL -- ⚠️ n_income / revenue 都是 double precision，PG 的 round(double, int) 不存在， -- 必须先转 numeric 再 round，否则报 function round(double precision, integer) does not exist ELSE ROUND(((r.n_income / r.revenue) * 100)::numeric, 2) END AS profit_margin FROM kline k LEFT JOIN latest_basic b ON b.symbol = k.symbol LEFT JOIN latest_report r ON r.symbol = k.symbol
